mapper.select:

where b.role_id = #{id}

    AND name like concat('%', #{name}, '%')


    AND state = #{state}

order by parent_id,sort


where b.role_id in

    #{roleId}


    AND name like concat('%', #{name}, '%')


    AND state = #{state}

GROUP BY a.id
order by parent_id,sort

select a.id,parent_id,name,type,url,path,state,ifnull(perms,'') as perms,icon, sort,visible,active_menu from sys_menu a where perms in
#{itemValue}
order by parent_id,sort
